    "Access key ID": ["एक्सेस कुंजी ID", "ID de clave de acceso", "ID de clé d’accès", "Zugriffsschlüssel-ID", "アクセスキーID", "访问密钥 ID", "معرّف مفتاح الوصول"],
    "Secret access key": ["गुप्त एक्सेस कुंजी", "Clave de acceso secreta", "Clé d’accès secrète", "Geheimer Zugriffsschlüssel", "シークレットアクセスキー", "私有访问密钥", "مفتاح الوصول السري"],
    "Session token (optional)": ["सत्र टोकन (वैकल्पिक)", "Token de sesión (opcional)", "Jeton de session (facultatif)", "Sitzungstoken (optional)", "セッショントークン（任意）", "会话令牌（可选）", "رمز الجلسة (اختياري)"],
    "Path-style bucket addressing": ["पथ-शैली बकेट एड्रेसिंग", "Direccionamiento de buckets por ruta", "Adressage des compartiments par chemin", "Pfadbasierte Bucket-Adressierung", "パス形式のバケットアドレス", "路径式存储桶寻址", "عنونة الحاويات بأسلوب المسار"],
    "Allow unencrypted HTTP for this development endpoint": ["इस विकास एंडपॉइंट पर अनएन्क्रिप्टेड HTTP की अनुमति दें", "Permitir HTTP sin cifrar para este endpoint de desarrollo", "Autoriser HTTP non chiffré pour ce point d’accès de développement", "Unverschlüsseltes HTTP für diesen Entwicklungsendpunkt erlauben", "この開発用エンドポイントで暗号化されていないHTTPを許可", "允许此开发端点使用未加密的 HTTP", "السماح بـHTTP غير المشفر لنقطة الاتصال التطويرية هذه"],
    "Clear connection and results": ["कनेक्शन और परिणाम साफ़ करें", "Borrar conexión y resultados", "Effacer la connexion et les résultats", "Verbindung und Ergebnisse leeren", "接続と結果を消去", "清除连接和结果", "مسح الاتصال والنتائج"],
    "Saved S3 connection settings are invalid.": ["सहेजी गई S3 कनेक्शन सेटिंग अमान्य हैं।", "Los ajustes guardados de conexión S3 no son válidos.", "Les paramètres de connexion S3 enregistrés sont invalides.", "Die gespeicherten S3-Verbindungseinstellungen sind ungültig.", "保存済みのS3接続設定が無効です。", "已保存的 S3 连接设置无效。", "إعدادات اتصال S3 المحفوظة غير صالحة."],
    "Bucket browser": ["बकेट ब्राउज़र", "Explorador de buckets", "Explorateur de compartiments", "Bucket-Übersicht", "バケットの参照", "存储桶浏览器", "متصفح الحاويات"],
    "Buckets": ["बकेट", "Buckets", "Compartiments", "Buckets", "バケット", "存储桶", "الحاويات"],
    "List buckets": ["बकेट की सूची", "Listar buckets", "Lister les compartiments", "Buckets auflisten", "バケットを一覧表示", "列出存储桶", "عرض الحاويات"],
    "Next bucket page": ["बकेट का अगला पेज", "Página siguiente de buckets", "Page suivante des compartiments", "Nächste Bucket-Seite", "バケットの次ページ", "下一页存储桶", "صفحة الحاويات التالية"],
    "Bucket listing may require account-level permission. You can enter a known bucket below without listing the account.": ["बकेट सूची के लिए खाता-स्तर अनुमति लग सकती है। खाता सूची बिना नीचे ज्ञात बकेट डाल सकते हैं।", "Listar buckets puede requerir permisos de cuenta. Puedes introducir uno conocido abajo sin listar la cuenta.", "Lister les compartiments peut exiger une autorisation au niveau du compte. Vous pouvez saisir un compartiment connu sans lister le compte.", "Bucket-Listen können Kontoberechtigungen erfordern. Ein bekannter Bucket kann unten ohne Kontoliste eingegeben werden.", "バケット一覧にはアカウントレベルの権限が必要な場合があります。一覧取得せずに既知のバケット名を入力できます。", "列出存储桶可能需要账户级权限。无需列出账户即可在下方输入已知存储桶。", "قد يتطلب عرض الحاويات إذنًا على مستوى الحساب. يمكنك إدخال حاوية معروفة أدناه دون عرض الحساب."],
    "Buckets on this page: {count}": ["इस पेज पर बकेट: {count}", "Buckets en esta página: {count}", "Compartiments sur cette page : {count}", "Buckets auf dieser Seite: {count}", "このページのバケット数：{count}", "此页存储桶数：{count}", "الحاويات في هذه الصفحة: {count}"],
    "Partial page; use the next token if available.": ["आंशिक पेज; उपलब्ध हो तो अगला टोकन उपयोग करें।", "Página parcial; usa el siguiente token si está disponible.", "Page partielle ; utilisez le jeton suivant s’il est disponible.", "Unvollständige Seite; falls verfügbar, nächstes Token verwenden.", "一部のページです。次のトークンがあれば使用してください。", "页面不完整；如有下一令牌，请使用它继续。", "صفحة جزئية؛ استخدم الرمز التالي إن توفر."],
    "Creation date unavailable": ["निर्माण तिथि उपलब्ध नहीं", "Fecha de creación no disponible", "Date de création indisponible", "Erstellungsdatum nicht verfügbar", "作成日時は取得できません", "创建日期不可用", "تاريخ الإنشاء غير متاح"],
